const uint32_t zmath_testing_oracle_operation_table_count =
    ZMATH_TESTING_ORACLE_OPERATION_COUNT;

#if defined(__cplusplus)
static_assert(
    ZMATH_TESTING_ORACLE_ARRAY_COUNT(zmath_testing_oracle_operation_table) ==
        ZMATH_TESTING_ORACLE_OPERATION_COUNT,
    "oracle operation table count drift"
);
#else
_Static_assert(
    ZMATH_TESTING_ORACLE_ARRAY_COUNT(zmath_testing_oracle_operation_table) ==
        ZMATH_TESTING_ORACLE_OPERATION_COUNT,
    "oracle operation table count drift"
);
#endif

static int zmath_testing_oracle_field_descriptor_equal(
    const zmath_testing_oracle_field_descriptor *left,
    const zmath_testing_oracle_field_descriptor *right
) {
    if (left->kind != right->kind) return 0;
    if (left->value_bits != right->value_bits) return 0;
    if (left->format.code != right->format.code) return 0;
    if (left->format.storage_bits != right->format.storage_bits) return 0;
    if (left->format.exponent_bits != right->format.exponent_bits) return 0;
    if (left->format.fraction_bits != right->format.fraction_bits) return 0;
    if (left->format.reserved != right->format.reserved) return 0;
    return left->reserved == right->reserved;
}

static int zmath_testing_oracle_operation_matches_request(
    const zmath_testing_oracle_operation_signature *signature,
    const zmath_testing_oracle_request *request
) {
    if (request == NULL) return 0;
    if (request->abi_version != ZMATH_TESTING_ORACLE_ABI_VERSION) return 0;
    if (request->operation == NULL) return 0;
    if (request->operation_length != signature->operation_length) return 0;
    for (uint32_t index = 0; index < signature->operation_length; ++index) {
        if (request->operation[index] != signature->operation[index]) return 0;
    }
    if (request->arity != signature->arity) return 0;
    if (request->input_field_count != signature->arity) return 0;
    if (request->input_fields == NULL) return 0;
    for (uint32_t index = 0; index < signature->arity; ++index) {
        if (!zmath_testing_oracle_field_descriptor_equal(
                &request->input_fields[index].descriptor,
                &signature->arguments[index]))
        {
            return 0;
        }
    }
    if (request->result_layout != signature->result_layout) return 0;
    if (request->structure_kind != signature->structure_kind) return 0;
    if (request->result_field_count != signature->result_field_count) return 0;
    if (request->result_fields == NULL) return 0;
    for (uint32_t index = 0; index < signature->result_field_count; ++index) {
        if (!zmath_testing_oracle_field_descriptor_equal(
                &request->result_fields[index],
                &signature->result_fields[index]))
        {
            return 0;
        }
    }
    return 1;
}

const zmath_testing_oracle_operation_signature *
zmath_testing_oracle_find_operation_signature(
    const zmath_testing_oracle_request *request
) {
    if (request == NULL) return NULL;
    for (uint32_t index = 0; index < zmath_testing_oracle_operation_table_count; ++index) {
        const zmath_testing_oracle_operation_signature *signature =
            &zmath_testing_oracle_operation_table[index];
        if (zmath_testing_oracle_operation_matches_request(signature, request)) {
            return signature;
        }
    }
    return NULL;
}

